  2262  M3Result  CompileBlock  (IM3Compilation o, IM3FuncType i_blockType, m3opcode_t i_blockOpcode)
  2263  {
  2264      M3Result result;                                                                    d_m3Assert (not IsRegisterAllocated (o, 0));
  2265                                                                                          d_m3Assert (not IsRegisterAllocated (o, 1));
  2266      M3CompilationScope outerScope = o->block;
  2267      M3CompilationScope * block = & o->block;
  2268
  2269      block->outer            = & outerScope;
  2270      block->pc               = GetPagePC (o->page);
  2271      block->patches          = NULL;
  2272      block->type             = i_blockType;
  2273      block->initStackIndex   = o->stackIndex;
  2274      block->depth            ++;
  2275      block->opcode           = i_blockOpcode;
  2276
  2277  _   (Compile_BlockStatements (o));
  2278
  2279      bool moveStackTopToRegister;
  2280  _   (ValidateBlockEnd (o, & moveStackTopToRegister));
  2281
  2282      if (moveStackTopToRegister)
  2283  _       (MoveStackTopToRegister (o));
  2284
  2285      PatchBranches (o);
  2286
  2287      o->block = outerScope;
  2288
  2289      _catch: return result;
  2290  }
