  2293  M3Result  CompileLocals  (IM3Compilation o)
  2294  {
  2295      M3Result result;
  2296
  2297      u32 numLocalBlocks;
  2298  _   (ReadLEB_u32 (& numLocalBlocks, & o->wasm, o->wasmEnd));
  2299
  2300      for (u32 l = 0; l < numLocalBlocks; ++l)
  2301      {
  2302          u32 varCount;
  2303          i8 waType;
  2304          u8 localType;
  2305
  2306  _       (ReadLEB_u32 (& varCount, & o->wasm, o->wasmEnd));
  2307  _       (ReadLEB_i7 (& waType, & o->wasm, o->wasmEnd));
  2308  _       (NormalizeType (& localType, waType));
  2309                                                                                                  m3log (compile, "pushing locals. count: %d; type: %s", varCount, c_waTypes [localType]);
  2310          while (varCount--)
  2311  _           (PushAllocatedSlot (o, localType));
  2312      }
  2313
  2314      _catch: return result;
  2315  }
