  2318  M3Result  Compile_ReserveConstants  (IM3Compilation o)
  2319  {
  2320      M3Result result = m3Err_none;
  2321
  2322      // in the interest of speed, this blindly scans the Wasm code looking for any byte
  2323      // that looks like an const opcode.
  2324      u32 numConstantSlots = 0;
  2325
  2326      bytes_t wa = o->wasm;
  2327      while (wa < o->wasmEnd)
  2328      {
  2329          u8 code = * wa++;
  2330
  2331          if (code == 0x41 or code == 0x43)       // i32, f32
  2332              numConstantSlots += 1;
  2333          else if (code == 0x42 or code == 0x44)  // i64, f64
  2334              numConstantSlots += GetTypeNumSlots (c_m3Type_i64);
  2335      }
  2336
  2337      // if constants overflow their reserved stack space, the compiler simply emits op_Const
  2338      // operations as needed. Compiled expressions (global inits) don't pass through this
  2339      // ReserveConstants function and thus always produce inline constants.
  2340      u32 cappedConstantSlots = M3_MIN (numConstantSlots, d_m3MaxConstantTableSize);           m3log (compile, "estimated constant slots: %d; reserved: %d", numConstantSlots, cappedConstantSlots)
  2341
  2342  //  cappedConstantSlots = 1;
  2343
  2344      o->firstDynamicSlotIndex = o->firstConstSlotIndex + cappedConstantSlots;
  2345
  2346      if (o->firstDynamicSlotIndex >= d_m3MaxFunctionSlots)
  2347          result = m3Err_functionStackOverflow;
  2348
  2349      return result;
  2350  }
