  2361  M3Result  Compile_Function  (IM3Function io_function)
  2362  {
  2363      IM3FuncType funcType = io_function->funcType;
  2364
  2365      M3Result result = m3Err_none;                                   m3log (compile, "compiling: '%s'; wasm-size: %d; numArgs: %d; return: %s",
  2366                                                                             m3_GetFunctionName(io_function), (u32) (io_function->wasmEnd - io_function->wasm), GetFunctionNumArgs (io_function),
  2367                                                                             c_waTypes [GetSingleRetType(funcType)]);
  2368      IM3Runtime runtime = io_function->module->runtime;
  2369
  2370      IM3Compilation o = & runtime->compilation;                      d_m3Assert (d_m3MaxFunctionSlots >= d_m3MaxFunctionStackHeight * (d_m3Use32BitSlots + 1))  // need twice as many slots in 32-bit mode
  2371      SetupCompilation (o);
  2372
  2373      o->runtime  = runtime;
  2374      o->module   = io_function->module;
  2375      o->function = io_function;
  2376      o->wasm     = io_function->wasm;
  2377      o->wasmEnd  = io_function->wasmEnd;
  2378      o->block.type = funcType;
  2379
  2380  _try {
  2381      // skip over code size. the end was already calculated during parse phase
  2382      u32 size;
  2383  _   (ReadLEB_u32 (& size, & o->wasm, o->wasmEnd));                  d_m3Assert (size == (o->wasmEnd - o->wasm))
  2384
  2385  _   (AcquireCompilationCodePage (o, & o->page));
  2386
  2387      pc_t pc = GetPagePC (o->page);
  2388
  2389      // all args & returns are 64-bit aligned, so use 2 slots for a d_m3Use32BitSlots=1 build
  2390      const u32 ioSlotCount = sizeof (u64) / sizeof (m3slot_t);
  2391
  2392      u32 numRetSlots = GetFunctionNumReturns (o->function) * ioSlotCount;
  2393
  2394      for (u32 i = 0; i < numRetSlots; ++i)
  2395          MarkSlotAllocated (o, i);
  2396
  2397      o->function->numRetSlots = o->firstDynamicSlotIndex = numRetSlots;
  2398
  2399      u32 numArgs = GetFunctionNumArgs (o->function);
  2400
  2401      // push the arg types to the type stack
  2402      for (u32 i = 0; i < numArgs; ++i)
  2403      {
  2404          u8 type = GetFunctionArgType (o->function, i);
  2405  _       (PushAllocatedSlot (o, type));
  2406
  2407          if (i < numArgs - 1)
  2408          {
  2409              // prevent allocator fill-in
  2410              o->firstDynamicSlotIndex += ioSlotCount;
  2411          }
  2412          else
  2413          {
  2414              // final arg only allocates its natural width when using 32-bit slots
  2415              o->firstDynamicSlotIndex += GetTypeNumSlots (type);
  2416          }
  2417      }
  2418
  2419      //o->maxAllocatedSlotPlusOne =
  2420      o->function->numRetAndArgSlots = o->firstLocalSlotIndex = o->firstDynamicSlotIndex;
  2421
  2422  _   (CompileLocals (o));
  2423
  2424      u16 maxSlot = GetMaxUsedSlotPlusOne (o);
  2425
  2426      o->function->numLocalBytes = (maxSlot - o->firstLocalSlotIndex) * sizeof (m3slot_t);
  2427
  2428      o->firstConstSlotIndex = o->maxConstSlotIndex = maxSlot;
  2429
  2430      // ReserveConstants initializes o->firstDynamicSlotIndex
  2431  _   (Compile_ReserveConstants (o));
  2432
  2433      // start tracking the max stack used (Push() also updates this value) so that op_Entry can precisely detect stack overflow
  2434      o->function->maxStackSlots = o->maxAllocatedSlotPlusOne = o->firstDynamicSlotIndex;
  2435
  2436      o->block.initStackIndex = o->firstDynamicStackIndex = o->stackIndex;                           m3log (compile, "start stack index: %d", (u32) o->firstDynamicStackIndex);
  2437
  2438  _   (EmitOp (o, op_Entry));
  2439      EmitPointer (o, io_function);
  2440
  2441  _   (Compile_BlockStatements (o));
  2442
  2443      io_function->compiled = pc;
  2444
  2445      u32 numConstantSlots = o->maxConstSlotIndex - o->firstConstSlotIndex;       m3log (compile, "unique constant slots: %d; unused slots: %d", numConstantSlots, o->firstDynamicSlotIndex - o->maxConstSlotIndex);
  2446
  2447      io_function->numConstantBytes = numConstantSlots * sizeof (m3slot_t);
  2448
  2449      if (numConstantSlots)
  2450      {
  2451          io_function->constants = m3_CopyMem(o->constants, io_function->numConstantBytes);
  2452          _throwifnull(io_function->constants);
  2453      }
  2454
  2455  } _catch:
  2456
  2457      ReleaseCompilationCodePage (o);
  2458
  2459      return result;
  2460  }
