    41              m3_Free (page);
    42              return NULL;
    43          }
    44          page->info.mapping->basePC = GetPageStartPC(page);
    45  #endif // d_m3RecordBacktraces
    46
    47          m3log (runtime, "new page: %p; seq: %d; bytes: %d; lines: %d", GetPagePC (page), page->info.sequence, pageSize, page->info.numLines);
