   110  IM3CodePage RemoveCodePageOfCapacity (M3CodePage ** io_list, u32 i_minimumLineCount)
   111  {
   112      IM3CodePage prev = NULL;
   113      IM3CodePage page = * io_list;
   114
   115      while (page)
   116      {
   117          if (NumFreeLines (page) >= i_minimumLineCount)
   118          {                                                           d_m3Assert (page->info.usageCount == 0);
   119              IM3CodePage next = page->info.next;
   120              if (prev)
   121                  prev->info.next = next; // mid-list
   122              else
   123                  * io_list = next;       // front of list
   124
   125              break;
   126          }
   127
   128          prev = page;
   129          page = page->info.next;
   130      }
   131
   132      return page;
   133  }
